// HasExit applies the HasEdge predicate on the "exit" edge.
func HasExit() predicate.ExitBinding {
	return predicate.ExitBinding(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ExitTable, ExitColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasExitWith applies the HasEdge predicate on the "exit" edge with a given conditions (other predicates).
func HasExitWith(preds ...predicate.Exit) predicate.ExitBinding {
	return predicate.ExitBinding(func(s *sql.Selector) {
		step := newExitStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ExitBinding) predicate.ExitBinding {
	return predicate.ExitBinding(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ExitBinding) predicate.ExitBinding {
	return predicate.ExitBinding(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ExitBinding) predicate.ExitBinding {
	return predicate.ExitBinding(sql.NotPredicates(p))
}
